import type pg from 'pg';
import { pool, transaction } from '../../../packages/database/src/pool.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: string;
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ClaimedErasureRequest extends ErasureRequestRow {
  max_attempts: number;
}

export function erasureRequestHash(customerId: string): string {
  return createHash('sha256').update(JSON.stringify({ customerId })).digest('hex');
}

export class ErasureRepository {
  /**
   * Returns the existing request for a customer, if any. Used to short-circuit
   * creation: a customer may have at most one erasure request.
   */
  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findByIdForMerchant(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  /**
   * Creates an erasure request honoring idempotency. Returns the request that
   * applies, or throws a 409-shaped error when an idempotency key is reused for
   * a different customer.
   */
  async createRequest(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
    requestHash: string,
  ): Promise<ErasureRequestRow> {
    return await transaction(async (client) => {
      await client.query('SELECT pg_advisory_xact_lock(hashtext($1))', `erasure:${merchantId}:${customerId}`);
      const existing = await this.findByCustomerWithClient(client, merchantId, customerId);
      if (existing) return existing;

      const inserted = await client.query<ErasureRequestRow>(
        `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key,request_hash)
         VALUES($1,$2,$3,$4)
         ON CONFLICT DO NOTHING
         RETURNING id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at`,
        [merchantId, customerId, idempotencyKey, requestHash],
      );
      if (inserted.rows[0]) return inserted.rows[0]!;

      const byCustomer = await this.findByCustomerWithClient(client, merchantId, customerId);
      if (byCustomer) return byCustomer;

      const byKey = await client.query<ErasureRequestRow>(
        `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
         FROM customers.erasure_requests WHERE merchant_id=$1 AND idempotency_key=$2`,
        [merchantId, idempotencyKey],
      );
      const reused = byKey.rows[0];
      if (reused && reused.customer_id !== customerId) {
        throw Object.assign(new Error('idempotency_key_reused_for_different_customer'), { statusCode: 409 });
      }
      return reused!;
    });
  }

  private async findByCustomerWithClient(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async recoverExpiredLeases(): Promise<number> {
    const result = await pool.query(
      `UPDATE customers.erasure_requests
       SET status='pending', available_at=now(), locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
           last_error=COALESCE(last_error,'worker_lease_expired')
       WHERE status='processing' AND lease_expires_at<now()`,
    );
    return result.rowCount ?? 0;
  }

  async claim(workerId: string, leaseSeconds = 60): Promise<ClaimedErasureRequest | undefined> {
    return await transaction(async (client) => {
      const result = await client.query<ClaimedErasureRequest>(
        `UPDATE customers.erasure_requests
         SET status='processing', attempts=attempts+1, locked_by=$1, locked_at=now(),
             lease_expires_at=now()+($2 || ' seconds')::interval, available_at=NULL, last_error=NULL
         WHERE id=(SELECT id FROM customers.erasure_requests
           WHERE status IN ('pending','failed') AND available_at<=now()
           ORDER BY available_at, created_at FOR UPDATE SKIP LOCKED LIMIT 1)
         RETURNING id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at,max_attempts`,
        [workerId, leaseSeconds],
      );
      return result.rows[0];
    });
  }

  async complete(client: pg.PoolClient, request: ClaimedErasureRequest): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', completed_at=now(), updated_at=now(),
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL, available_at=NULL, last_error=NULL
       WHERE id=$1`,
      [request.id],
    );
  }

  async fail(client: pg.PoolClient, request: ClaimedErasureRequest, errorCode: string): Promise<void> {
    const exhausted = request.attempts >= request.max_attempts;
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='failed', last_error=$2, updated_at=now(),
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
           available_at=${exhausted ? 'NULL' : 'now()+($3 || \' seconds\')::interval'}
       WHERE id=$1`,
      exhausted ? [request.id, errorCode] : [request.id, errorCode, boundedBackoff(request.attempts)],
    );
  }
}

function boundedBackoff(attempts: number, maximum = 300): number {
  return Math.min(maximum, 2 ** Math.max(0, attempts));
