import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { CustomerRepository } from './repository.js';
import { ErasureRepository, erasureRequestHash, type ClaimedErasureRequest, type ErasureRequestRow } from './erasure-repository.js';

export interface ErasureRequestView {
  id: string;
  customerId: string;
  status: string;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

function toView(row: ErasureRequestRow): ErasureRequestView {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureService {
  constructor(
    private readonly repository = new ErasureRepository(),
    private readonly customers = new CustomerRepository(),
  ) {}

  async create(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestView> {
    if (idempotencyKey.length < 8 || idempotencyKey.length > 200) {
      throw Object.assign(new Error('valid_idempotency_key_required'), { statusCode: 400 });
    }
    const customer = await this.customers.find(merchantId, customerId);
    if (!customer) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
    const row = await this.repository.createRequest(merchantId, customerId, idempotencyKey, erasureRequestHash(customerId));
    return toView(row);
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestView | undefined> {
    const row = await this.repository.findByIdForMerchant(merchantId, requestId);
    return row ? toView(row) : undefined;
  }

  /** Erases the customer's personal data while retaining financially correct records. */
  async erase(request: ClaimedErasureRequest, redis: Redis): Promise<void> {
    const { merchant_id: merchantId, customer_id: customerId } = request;
    await transaction(async (client) => {
      await this.scrubCustomerRecord(client, merchantId, customerId);
      await this.deleteCustomerPii(client, merchantId, customerId);
      await this.scrubFinancialRecords(client, merchantId, customerId);
      await this.scrubOperationsPii(client, merchantId, customerId);
      await this.repository.complete(client, request);
    });
    await this.purgeExternalProjections(merchantId, customerId, redis);
    await this.anonymizeStoredDocuments(merchantId, customerId);
  }

  private async scrubCustomerRecord(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    const redactedEmail = `erased_${customerId.replace(/-/g, '')}@redacted.payflow`;
    const redactedReference = `erased:${customerId}`;
    await client.query(
      `UPDATE customers.customers
       SET email=$3, name='ERASED', phone=NULL, external_reference=$4, metadata='{}'::jsonb,
           status='erased', updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId, redactedEmail, redactedReference],
    );
  }

  private async deleteCustomerPii(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`, [merchantId, customerId]);

    // Support tickets: remove this customer's messages and participation. Whole
    // tickets are deleted only when this customer was the sole participant, so
    // shared threads for other customers are preserved.
    await client.query(
      `DELETE FROM customers.support_messages
       WHERE ticket_id IN (SELECT ticket_id FROM customers.support_participants WHERE customer_id=$1)
         AND author_type='customer' AND author_id=$1`,
      [customerId],
    );
    await client.query(
      `DELETE FROM customers.support_participants WHERE customer_id=$1`,
      [customerId],
    );
    await client.query(
      `DELETE FROM customers.support_tickets t
       WHERE t.merchant_id=$1
         AND NOT EXISTS (SELECT 1 FROM customers.support_participants p WHERE p.ticket_id=t.id)`,
      [merchantId],
    );
  }

  private async scrubFinancialRecords(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    // Retain payment history but drop identifying snapshots. The customer_id
    // reference is an internal handle to the anonymized customer record, not PII.
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=jsonb_build_object('id',customer_id,'status','erased'), updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.refunds
       SET customer_email=NULL
       WHERE payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=jsonb_build_object('status','erased')
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async scrubOperationsPii(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.analytics_events
       SET email=NULL,
           properties=(properties - 'email' - 'name' - 'phone' - 'customerEmail' - 'externalReference')
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(`DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  }

  private async purgeExternalProjections(merchantId: string, customerId: string, redis: Redis): Promise<void> {
    const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
    await redis.del(cacheKey, `${cacheKey}:activity`);
    try {
      await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: false });
    } catch {
      // The document may not exist yet if no projection ran; deletion is best-effort.
    }
  }

  private async anonymizeStoredDocuments(merchantId: string, customerId: string): Promise<void> {
    const manifests = await pool.query<{ object_key: string; document_type: string }>(
      `SELECT object_key, document_type FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2 AND document_type IN ('receipt','invoice')`,
      [merchantId, customerId],
    );
    for (const manifest of manifests.rows) {
      try {
        await this.anonymizeObject(manifest.object_key);
        await pool.query(
          `UPDATE operations.document_manifests SET checksum=$2, metadata=jsonb_set(metadata,'{anonymized}', 'true')
           WHERE object_key=$1`,
          [manifest.object_key, await this.checksumFor(manifest.object_key)],
        );
      } catch {
        // Object already removed or unreadable; leave the manifest intact.
      }
    }
  }

  private async anonymizeObject(objectKey: string): Promise<void> {
    const response = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
    const body = JSON.parse((await response.stream.toArray()).toString()) as Record<string, unknown>;
    if (typeof body === 'object' && body !== null) {
      body.customer = { status: 'erased' };
      body.customerEmail = undefined;
      if (typeof body.billing === 'object' && body.billing !== null) body.billing = { status: 'erased' };
    }
    const content = JSON.stringify(body);
    await objectStore.putObject(DOCUMENT_BUCKET, objectKey, content, Buffer.byteLength(content), { 'Content-Type': 'application/json' });
  }

  private async checksumFor(objectKey: string): Promise<string> {
    const response = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
    const content = (await response.stream.toArray()).toString();
    return createHashHex(content);
  }
}

