 * the work safely resumes after a crash or restart, and every cleanup step is
 * idempotent so retries converge on the same result without duplicating work.
 */
export async function startErasureWorker(signal: AbortSignal, redis: Redis): Promise<void> {
  const repository = new ErasureRepository();
  const service = new ErasureService();
  let lastLeaseRecovery = 0;

  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await repository.recoverExpiredLeases();
      lastLeaseRecovery = Date.now();
    }
    const request = await repository.claim(workerId());
    if (!request) {
      await new Promise((resolve) => setTimeout(resolve, 250));
      continue;
    }
    await runOnce(service, repository, request, redis);
  }
}

