    const readable = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
    const body = JSON.parse(await readStream(readable)) as Record<string, unknown>;
    if (typeof body === 'object' && body !== null) {
      body.customer = { status: 'erased' };
      body.customerEmail = undefined;
      if (typeof body.billing === 'object' && body.billing !== null) body.billing = { status: 'erased' };
