  async erase(request: ClaimedErasureRequest, redis: Redis): Promise<void> {
    const { merchant_id: merchantId, customer_id: customerId } = request;
    // Database scrub is idempotent, so it is safe to re-run on retry. The request
    // is only marked complete after every active store is cleaned, so `completed`
    // guarantees the personal data is gone.
    await transaction(async (client) => {
      await this.scrubCustomerRecord(client, merchantId, customerId);
      await this.deleteCustomerPii(client, merchantId, customerId);
      await this.scrubFinancialRecords(client, merchantId, customerId);
      await this.scrubOperationsPii(client, merchantId, customerId);
    });
    await this.purgeExternalProjections(merchantId, customerId, redis);
    await this.anonymizeStoredDocuments(merchantId, customerId);
    await transaction(async (client) => await this.repository.complete(client, request));
